/* @lc app=leetcode id=3414 lang=kotlin */ class Solution { fun cmp(a: List<Int>, b: List<Int>): Int = a.zip(b).firstOrNull { (x, y) -> x != y }?.let { (x, y) -> x.compareTo(y) } ?: a.size.compareTo(b.size) fun bt(a: Pair<Long, List<Int>>, b: Pair<Long, List<Int>>): Pair<Long, List<Int>> = if (a.first != b.first) (if (a.first > b.first) a else b) else if (cmp(a.second, b.second) <= 0) a else b fun maximumWeight(intervals: List<List<Int>>): IntArray = intervals.indices.sortedBy { intervals[it][0] }.let { ord -> ord.map { intervals[it][0] }.let { ls -> ord.size.let { n -> (0..n).map { Array(5) { 0L to listOf<Int>() } }.let { dp -> (n - 1 downTo 0).forEach { i -> generateSequence(0 to n) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (ls[m] <= intervals[ord[i]][1]) m + 1 to hi else lo to m } }.last().first.let { nx -> (1..4).forEach { k -> dp[i][k] = bt(dp[i + 1][k], dp[nx][k - 1].let { (s, l) -> s + intervals[ord[i]][2] to (l + ord[i]).sorted() }) } } }.let { dp[0][4].second.toIntArray() } } } } } }